<script lang="ts">
 import {today,type Project,type Account} from './model';import {holderAt,accountOpenOn,propertyDetails} from './account-data';import {translator} from './i18n';import {displayDate} from './date-format';import RecordToolbar from './RecordToolbar.svelte';import AccountLookupField from './AccountLookupField.svelte';
 export let project:Project;export let onadd:()=>void;export let oncopy:(a:Account)=>void;export let onedit:(a:Account,date:string)=>void;export let onmark:(a:Account)=>void;export let parentId='accounts';export let onchoose:((id:string)=>void)|undefined=undefined;export let multiple=false;export let selectedIds:string[]=[];
 let date=today(),selected='',filters={locality:'',street:'',building:'',property:'',holder:'',number:''},enabled:Record<string,boolean>={},applied:typeof filters|null=null,comparison='contains';
 $:t=translator(project.settings.language);$:current=project.accounts.find(a=>a.id===selected);
 function apply(){applied=Object.fromEntries(Object.entries(filters).map(([key,value])=>[key,enabled[key]?value:''])) as typeof filters;}
 function clear(){filters={locality:'',street:'',building:'',property:'',holder:'',number:''};enabled={};applied=null;}
 $:rows=project.accounts.filter(a=>{if((a.opening_date||a.opening_period+'-01')>date)return false;if(!applied)return true;const details=propertyDetails(project,a),holder=holderAt(project,a,date).name,match=(s:string,q:string)=>!q||(comparison==='equal'?s.toLocaleLowerCase()===q.toLocaleLowerCase():comparison==='starts'?s.toLocaleLowerCase().startsWith(q.toLocaleLowerCase()):s.toLocaleLowerCase().includes(q.toLocaleLowerCase()));return (!applied.locality||details.locality?.id===applied.locality)&&(!applied.street||details.street?.id===applied.street)&&(!applied.building||details.building?.id===applied.building)&&match(details.property?.attributes.number||a.apartments.join(', '),applied.property)&&match(holder,applied.holder)&&match(a.number,applied.number);}).sort((a,b)=>a.number.localeCompare(b.number,undefined,{numeric:true}));
</script>
<div class="account-list"><div class="list-top"><label>{t('На дату','La data')}<input type="date" bind:value={date}/></label><button onclick={apply}>{t('Отбор','Filtrare')}</button><button onclick={clear}>{t('Снять отбор','Resetează filtrul')}</button></div>
 <div class="filters"><div>{#each [['locality','Населённый пункт','Localitate','localities'],['street','Улица','Stradă','streets'],['building','Здание','Clădire','buildings']] as field}<label class="filter-line"><input type="checkbox" bind:checked={enabled[field[0]]}/><span>{project.settings.language==='ru'?field[1]:field[2]}</span><AccountLookupField {project} {parentId} kind={field[3] as 'localities'|'streets'|'buildings'} value={filters[field[0] as 'locality'|'street'|'building']} clearable={false} onselect={id=>{filters={...filters,[field[0]]:id};enabled={...enabled,[field[0]]:true};}}/></label>{/each}<label class="filter-line"><input type="checkbox" bind:checked={enabled.property}/><span>{t('Номер объекта учёта','Număr obiect')}</span><input bind:value={filters.property}/></label></div>
 <div><label class="filter-line"><input type="checkbox" bind:checked={enabled.holder}/><span>{t('Ответственный','Responsabil')}</span><input bind:value={filters.holder}/></label><label class="filter-line"><input type="checkbox" bind:checked={enabled.number}/><span>{t('Номер Л/С','Număr cont')}</span><input bind:value={filters.number}/></label><label class="comparison">{t('Вид сравнения текста','Comparare text')}<select bind:value={comparison}><option value="contains">{t('Содержит','Conține')}</option><option value="equal">{t('Равно','Egal')}</option><option value="starts">{t('Начинается с','Începe cu')}</option></select></label></div></div>
 <RecordToolbar language={project.settings.language} selected={!!current} {onadd} oncopy={()=>current&&oncopy(current)} onedit={()=>current&&onedit(current,date)} onremove={()=>current&&onmark(current)} onrefresh={()=>selected=''} onfilter={apply} onclearfilter={clear} filterActive={!!applied}/>
 <div class="table-wrap"><table><thead><tr>{#if multiple}<th></th>{/if}<th>{t('№ лицевого счёта','Număr cont personal')}</th><th>{t('Ответственный','Responsabil')}</th><th>{t('Объект учёта','Obiect')}</th><th>{t('Статус','Stare')}</th></tr></thead><tbody>{#each rows as a}<tr class:selected={selected===a.id||selectedIds.includes(a.id)} class:marked={a.marked_for_deletion} onclick={()=>selected=a.id} ondblclick={()=>onchoose?onchoose(a.id):onedit(a,date)}>{#if multiple}<td><input type="checkbox" checked={selectedIds.includes(a.id)} aria-label={a.number} onchange={()=>onchoose?.(a.id)}/></td>{/if}<td>{a.number}</td><td>{holderAt(project,a,date).name}</td><td>{propertyDetails(project,a).property?.name||a.address}</td><td>{accountOpenOn(a,date)?t('Открыт','Deschis'):t('Закрыт','Închis')}</td></tr>{/each}</tbody></table></div>{#if !rows.length}<p>{t('Лицевые счета не найдены.','Nu s-au găsit conturi personale.')}</p>{/if}
</div>




<style>
.account-list{display:flex;flex-direction:column;gap:8px;padding:12px;min-width:0}.list-top{display:flex;align-items:center;gap:12px}.list-top label{display:flex;align-items:center;gap:8px}.list-top button{border:0;background:transparent;color:var(--text);padding:7px}.filters{display:grid;grid-template-columns:1fr 1fr;gap:14px}.filters>div{display:grid;gap:6px;align-content:start}.filter-line{display:grid;grid-template-columns:16px 145px minmax(0,1fr);gap:6px;align-items:center}.filter-line>input:not([type=checkbox]),select{width:100%;min-width:0;height:34px;box-sizing:border-box}.comparison{display:flex;gap:8px;align-items:center}.comparison select{width:180px}.table-wrap{overflow:auto}table{border-collapse:collapse;width:100%;min-width:620px}th,td{padding:7px;text-align:left}th{position:sticky;top:0;background:var(--surface);font-weight:600}tr.selected{background:#489bcb30}tr.marked{opacity:.6;text-decoration:line-through}@media(max-width:800px){.filters{grid-template-columns:1fr}}
.filters{grid-template-columns:repeat(2,minmax(0,1fr))}.filters>div{min-width:0}.comparison{display:grid;grid-template-columns:minmax(0,1fr) minmax(120px,180px);min-width:0;min-height:38px}.comparison select{width:100%;height:38px;line-height:normal;padding-block:6px}.filter-line{min-width:0}.filter-line :global(.lookup-field){min-width:0}@media(max-width:800px){.filters{grid-template-columns:minmax(0,1fr)}}
</style>
